pub const MAX_MANIFEST_BYTES: usize = 1_048_576;
pub const MAX_MANIFEST_ENTRIES: usize = 4_096;

// Object fields are declared in UTF-8 key order. Array order is checked rather
// than silently changed by serialization. IDs name content, not filesystem paths.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DatasetArtifactManifestV2 {
    pub dataset_scope: DatasetScope,
    pub kind: String,
    pub payload: Vec<PayloadEntry>,
    pub producer: Producer,
    pub redistribution: Redistribution,
    pub schema_version: u32,
    pub sources: Vec<SourceRecord>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DatasetScope {
    pub domain: String,
    pub language: String,
    pub selected_source: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PayloadEntry {
    pub bytes: u64,
    pub id: String,
    pub media_type: String,
    pub role: String,
    pub sha256: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Producer {
    pub config_sha256: String,
    pub script_sha256: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Redistribution {
    pub adapter: String,
    pub derived_model: String,
    pub raw_input: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SourceRecord {
    pub attribution: Attribution,
    pub content_id: String,
    pub license: License,
    pub reference: String,
    pub source_id: String,
    pub upstream_revision: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Attribution {
    pub content_id: String,
    pub references: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct License {
    pub content_id: String,
    pub identifier: String,
}

pub fn lower_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

pub(crate) fn bounded_label(value: &str, limit: usize) -> bool {
    !value.is_empty() && value.len() <= limit && !value.chars().any(char::is_control)
}

pub fn validate_manifest_structure(
    manifest: &DatasetArtifactManifestV2,
) -> Result<(), AcquisitionError> {
    if manifest.schema_version != 2 || manifest.kind != "dataset" {
        return Err(AcquisitionError::Schema);
    }
    if manifest.payload.is_empty()
        || manifest.sources.is_empty()
        || manifest.payload.len() > MAX_MANIFEST_ENTRIES
        || manifest.sources.len() > MAX_MANIFEST_ENTRIES
    {
        return Err(AcquisitionError::Inventory);
    }
    let scope = &manifest.dataset_scope;
    let rights = &manifest.redistribution;
    for label in [
        &scope.domain,
        &scope.language,
        &scope.selected_source,
        &rights.adapter,
        &rights.derived_model,
        &rights.raw_input,
    ] {
        if !bounded_label(label, 256) {
            return Err(AcquisitionError::Metadata);
        }
    }
    if !lower_sha256(&manifest.producer.config_sha256)
        || !lower_sha256(&manifest.producer.script_sha256)
    {
        return Err(AcquisitionError::Metadata);
    }
    if manifest
        .payload
        .windows(2)
        .any(|pair| pair[0].id.as_bytes() >= pair[1].id.as_bytes())
        || manifest
            .sources
            .windows(2)
            .any(|pair| pair[0].source_id.as_bytes() >= pair[1].source_id.as_bytes())
    {
        return Err(AcquisitionError::Inventory);
    }
    let mut total = 0_u64;
    for entry in &manifest.payload {
        if !bounded_label(&entry.id, 256)
            || !bounded_label(&entry.media_type, 256)
            || !bounded_label(&entry.role, 256)
            || !lower_sha256(&entry.sha256)
        {
            return Err(AcquisitionError::Metadata);
        }
        total = total
            .checked_add(entry.bytes)
            .ok_or(AcquisitionError::Size)?;
    }
    for source in &manifest.sources {
        if !bounded_label(&source.source_id, 256)
            || !bounded_label(&source.upstream_revision, 256)
            || !bounded_label(&source.reference, 16_384)
            || !bounded_label(&source.license.identifier, 256)
            || source.attribution.references.is_empty()
            || source.attribution.references.len() > 16
            || source
                .attribution
                .references
                .iter()
                .any(|reference| !bounded_label(reference, 16_384))
        {
            return Err(AcquisitionError::Metadata);
        }
        for id in [
            &source.content_id,
            &source.license.content_id,
            &source.attribution.content_id,
        ] {
            if manifest
                .payload
                .binary_search_by(|entry| entry.id.as_bytes().cmp(id.as_bytes()))
                .is_err()
            {
                return Err(AcquisitionError::Inventory);
            }
        }
    }
    Ok(())
}

// Serde still owns JSON serialization. This writer owns only the course's
// output-size invariant, including for a caller-constructed typed record.
struct ManifestBuffer {
    bytes: Vec<u8>,
    exceeded: bool,
}

impl Write for ManifestBuffer {
    fn write(&mut self, chunk: &[u8]) -> std::io::Result<usize> {
        if self
            .bytes
            .len()
            .checked_add(chunk.len())
            .is_none_or(|size| size > MAX_MANIFEST_BYTES)
        {
            self.exceeded = true;
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "manifest output bound",
            ));
        }
        self.bytes.extend_from_slice(chunk);
        Ok(chunk.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

pub fn canonical_manifest_bytes(
    manifest: &DatasetArtifactManifestV2,
) -> Result<Vec<u8>, AcquisitionError> {
    validate_manifest_structure(manifest)?;
    let mut buffer = ManifestBuffer {
        bytes: Vec::new(),
        exceeded: false,
    };
    serde_json::to_writer(&mut buffer, manifest).map_err(|_| {
        if buffer.exceeded {
            AcquisitionError::ManifestBound
        } else {
            AcquisitionError::Schema
        }
    })?;
    buffer
        .write_all(b"\n")
        .map_err(|_| AcquisitionError::ManifestBound)?;
    Ok(buffer.bytes)
}

pub fn parse_dataset_manifest(bytes: &[u8]) -> Result<DatasetArtifactManifestV2, AcquisitionError> {
    if bytes.len() > MAX_MANIFEST_BYTES {
        return Err(AcquisitionError::ManifestBound);
    }
    let manifest = serde_json::from_slice(bytes).map_err(|_| AcquisitionError::Schema)?;
    if canonical_manifest_bytes(&manifest)? != bytes {
        return Err(AcquisitionError::NonCanonical);
    }
    Ok(manifest)
}

// region:dataset-artifact-identity
pub fn artifact_id(
    manifest: &DatasetArtifactManifestV2,
) -> Result<ArtifactDigest, AcquisitionError> {
    Ok(sha256(&canonical_manifest_bytes(manifest)?))
}
// endregion:dataset-artifact-identity

// Content verification through standard readers and writers. No transport,
// directory layout, reserved filename or database implementation belongs here.

use sha2::{Digest, Sha256};
use std::io::{Read, Write};

use super::canonical_manifest::{
    DatasetArtifactManifestV2, MAX_MANIFEST_BYTES, PayloadEntry, artifact_id,
    parse_dataset_manifest,
};
use super::lineage::{AcquisitionError, DatasetPolicy};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedPayload {
    id: String,
    bytes: u64,
    sha256: String,
}
impl VerifiedPayload {
    pub fn id(&self) -> &str {
        &self.id
    }
    pub fn bytes(&self) -> u64 {
        self.bytes
    }
    pub fn sha256(&self) -> &str {
        &self.sha256
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedBundle {
    artifact_id: String,
    evidence_kind: String,
    payloads: Vec<VerifiedPayload>,
    total_bytes: u64,
}
impl VerifiedBundle {
    pub fn artifact_id(&self) -> &str {
        &self.artifact_id
    }
    pub fn evidence_kind(&self) -> &str {
        &self.evidence_kind
    }
    pub fn payloads(&self) -> &[VerifiedPayload] {
        &self.payloads
    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
}

/// A provider exposes a finite logical inventory and a reader starting at byte
/// zero for each selected payload. How it retrieves those bytes is its concern.
pub trait AssetSource {
    type Reader: Read;
    fn payload_ids(&mut self) -> Result<Vec<String>, AcquisitionError>;
    fn open_payload(&mut self, expected: &PayloadEntry) -> Result<Self::Reader, AcquisitionError>;
}

pub fn read_manifest<R: Read + ?Sized>(
    reader: &mut R,
) -> Result<DatasetArtifactManifestV2, AcquisitionError> {
    let mut bytes = Vec::new();
    reader
        .take(MAX_MANIFEST_BYTES as u64 + 1)
        .read_to_end(&mut bytes)
        .map_err(|_| AcquisitionError::Io)?;
    parse_dataset_manifest(&bytes)
}

// region:bounded-payload-verification
struct CheckingWriter<'a, W: ?Sized> {
    sink: &'a mut W,
    hash: Sha256,
    bytes: u64,
    limit: u64,
    oversized: bool,
}
impl<W: Write + ?Sized> Write for CheckingWriter<'_, W> {
    fn write(&mut self, chunk: &[u8]) -> std::io::Result<usize> {
        let retained = (chunk.len() as u64).min(self.limit - self.bytes) as usize;
        self.sink.write_all(&chunk[..retained])?;
        self.hash.update(&chunk[..retained]);
        self.bytes += retained as u64;
        if retained != chunk.len() {
            self.oversized = true;
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "content exceeds selected size",
            ));
        }
        Ok(retained)
    }
    fn flush(&mut self) -> std::io::Result<()> {
        self.sink.flush()
    }
}

/// Standard I/O performs streaming and propagates backend failures. The course
/// compares the selected length and digest, and never writes the excess byte
/// used to distinguish a true EOF from a same-prefix oversize stream.
/// The sink can contain an unverified prefix on failure. Its owner must keep
/// that prefix private; this function does not roll back arbitrary writers.
pub fn verify_payload_into<R: Read + ?Sized, W: Write + ?Sized>(
    expected: &PayloadEntry,
    reader: &mut R,
    sink: &mut W,
) -> Result<VerifiedPayload, AcquisitionError> {
    let read_limit = expected
        .bytes
        .checked_add(1)
        .ok_or(AcquisitionError::Size)?;
    let mut checked = CheckingWriter {
        sink: &mut *sink,
        hash: Sha256::new(),
        bytes: 0,
        limit: expected.bytes,
        oversized: false,
    };
    let copied = std::io::copy(&mut reader.take(read_limit), &mut checked);
    if checked.oversized {
        return Err(AcquisitionError::Size);
    }
    copied.map_err(|_| AcquisitionError::Io)?;
    if checked.bytes != expected.bytes {
        return Err(AcquisitionError::Size);
    }
    let digest = format!("{:x}", checked.hash.finalize());
    if digest != expected.sha256 {
        return Err(AcquisitionError::Hash);
    }
    sink.flush().map_err(|_| AcquisitionError::Io)?;
    Ok(VerifiedPayload {
        id: expected.id.clone(),
        bytes: expected.bytes,
        sha256: digest,
    })
}

pub fn verify_payload<R: Read + ?Sized>(
    expected: &PayloadEntry,
    reader: &mut R,
) -> Result<VerifiedPayload, AcquisitionError> {
    verify_payload_into(expected, reader, &mut std::io::sink())
}
// endregion:bounded-payload-verification

pub(crate) fn admit_inventory<S: AssetSource>(
    manifest: &DatasetArtifactManifestV2,
    policy: &DatasetPolicy,
    source: &mut S,
) -> Result<(), AcquisitionError> {
    policy.validate_manifest(manifest)?;
    let mut ids = source.payload_ids()?;
    if ids.len() != manifest.payload.len() {
        return Err(AcquisitionError::Inventory);
    }
    ids.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
    if !ids
        .iter()
        .zip(&manifest.payload)
        .all(|(id, expected)| id == &expected.id)
    {
        return Err(AcquisitionError::Inventory);
    }
    Ok(())
}

pub(crate) fn bundle_proof(
    manifest: &DatasetArtifactManifestV2,
    policy: &DatasetPolicy,
    payloads: Vec<VerifiedPayload>,
) -> Result<VerifiedBundle, AcquisitionError> {
    let total_bytes = payloads.iter().try_fold(0_u64, |sum, entry| {
        sum.checked_add(entry.bytes()).ok_or(AcquisitionError::Size)
    })?;
    Ok(VerifiedBundle {
        artifact_id: artifact_id(manifest)?.as_hex().into(),
        evidence_kind: policy.evidence_kind().into(),
        payloads,
        total_bytes,
    })
}

pub fn verify_bundle<S: AssetSource>(
    manifest: &DatasetArtifactManifestV2,
    policy: &DatasetPolicy,
    source: &mut S,
) -> Result<VerifiedBundle, AcquisitionError> {
    admit_inventory(manifest, policy, source)?;
    let mut verified = Vec::with_capacity(manifest.payload.len());
    for expected in &manifest.payload {
        verified.push(verify_payload(
            expected,
            &mut source.open_payload(expected)?,
        )?);
    }
    bundle_proof(manifest, policy, verified)
}

// A selected content declaration is independent of an untrusted candidate.
// Provenance agreement is not legal authorization, privacy or quality evidence.

use serde::{Deserialize, Serialize};
use std::fmt;

use super::canonical_manifest::{
    DatasetArtifactManifestV2, MAX_MANIFEST_BYTES, bounded_label, canonical_manifest_bytes,
};
use crate::artifact_identity::{ArtifactDigest, sha256};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum AcquisitionError {
    Schema,
    NonCanonical,
    ManifestBound,
    Inventory,
    Metadata,
    Policy,
    Size,
    Hash,
    Io,
    Incomplete,
    AlreadyPublished,
}

impl fmt::Display for AcquisitionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Do not include arbitrary backend credentials, content or locations.
        write!(f, "{self:?}")
    }
}
impl std::error::Error for AcquisitionError {}

pub const MAX_POLICY_CONFIG_BYTES: usize = MAX_MANIFEST_BYTES;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct SelectedContent {
    evidence_kind: String,
    manifest: DatasetArtifactManifestV2,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DatasetPolicy {
    selected: SelectedContent,
}

impl DatasetPolicy {
    /// The caller must select and authenticate this declaration independently
    /// of the candidate. Copying the candidate into this constructor proves
    /// only self-consistency, not agreement with a trusted selection.
    pub fn new(
        manifest: DatasetArtifactManifestV2,
        evidence_kind: impl Into<String>,
    ) -> Result<Self, AcquisitionError> {
        canonical_manifest_bytes(&manifest)?;
        let evidence_kind = evidence_kind.into();
        if !bounded_label(&evidence_kind, 256) {
            return Err(AcquisitionError::Metadata);
        }
        let policy = Self {
            selected: SelectedContent {
                evidence_kind,
                manifest,
            },
        };
        policy.config_bytes()?;
        Ok(policy)
    }

    pub fn from_config_bytes(bytes: &[u8]) -> Result<Self, AcquisitionError> {
        if bytes.len() > MAX_POLICY_CONFIG_BYTES {
            return Err(AcquisitionError::ManifestBound);
        }
        let selected: SelectedContent =
            serde_json::from_slice(bytes).map_err(|_| AcquisitionError::Schema)?;
        Self::new(selected.manifest, selected.evidence_kind)
    }

    pub fn config_bytes(&self) -> Result<Vec<u8>, AcquisitionError> {
        let mut bytes = serde_json::to_vec(&self.selected).map_err(|_| AcquisitionError::Schema)?;
        bytes.push(b'\n');
        if bytes.len() > MAX_POLICY_CONFIG_BYTES {
            return Err(AcquisitionError::ManifestBound);
        }
        Ok(bytes)
    }

    pub fn manifest(&self) -> &DatasetArtifactManifestV2 {
        &self.selected.manifest
    }

    pub fn evidence_kind(&self) -> &str {
        &self.selected.evidence_kind
    }

    pub fn digest(&self) -> Result<ArtifactDigest, AcquisitionError> {
        Ok(sha256(&self.config_bytes()?))
    }

    pub fn validate_manifest(
        &self,
        candidate: &DatasetArtifactManifestV2,
    ) -> Result<(), AcquisitionError> {
        canonical_manifest_bytes(candidate)?;
        if candidate != self.manifest() {
            return Err(AcquisitionError::Policy);
        }
        Ok(())
    }
}

